scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsCodeQuality(ast).accidentalGlobals(global.EcsConfig.getList('js.assignable_globals', []));
    var report = new global.EcsReport(engine, {
        ruleId: 'JS-002',
        title: 'Accidental global variable',
        recommendation: 'Declare the variable with var in the function that uses it. If a platform variable must be set (for example answer), add its name to the system property ecs.js.assignable_globals.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
